import{_ as n,c as r,a2 as a,o}from"./chunks/framework.BnrAgU0Y.js";const s="/bllm/assets/6a0ccf2fff5f9f96d98bbde4bc752abd.BycHqQKs.png",f=JSON.parse('{"title":"旅行规划代理","description":"旅行规划代理","frontmatter":{"title":"旅行规划代理","description":"旅行规划代理","layout":"doc"},"headers":[],"relativePath":"langflow/tutorials-travel-planning-agent.md","filePath":"langflow/tutorials-travel-planning-agent.md"}'),e={name:"langflow/tutorials-travel-planning-agent.md"};function l(g,t,i,p,h,c){return o(),r("div",null,t[0]||(t[0]=[a('<h1 id="旅行规划代理" tabindex="-1">旅行规划代理 <a class="header-anchor" href="#旅行规划代理" aria-label="Permalink to &quot;旅行规划代理&quot;">​</a></h1><p>构建一个用于代理应用的 <strong>旅行规划代理</strong> 流程，使用多个工具调用代理。</p><p>一个 <strong>代理</strong> 使用 LLM（大型语言模型）作为其“头脑”，以在连接的工具中进行选择，并完成其任务。</p><p>在此流程中，多个 <strong>工具调用代理</strong> 使用 <strong>Open AI</strong> 的 LLM 来规划旅行行程。每个代理都有不同的职责，由其 <strong>系统提示</strong> 字段定义。</p><p><strong>聊天输入</strong> 确定用户想去的目的地，并将结果传递给 <strong>城市选择</strong> 代理。<strong>本地专家</strong> 代理随后基于所选城市添加信息，而 <strong>旅行礼宾</strong> 负责汇总一份为期七天的旅行计划，并以 Markdown 格式呈现。</p><p>所有代理均可访问 <strong>搜索 API</strong> 和 <strong>URL 内容获取器</strong> 组件，而只有旅行礼宾可以使用 <strong>计算器</strong> 计算旅行费用。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>要使用此流程，您需要一个 <a href="https://platform.openai.com/" target="_blank" rel="noreferrer">OpenAI API 密钥</a> 和一个 <a href="https://www.searchapi.io/" target="_blank" rel="noreferrer">Search API 密钥</a>。</p><h2 id="打开-langflow-并开始一个新流程" tabindex="-1">打开 Langflow 并开始一个新流程 <a class="header-anchor" href="#打开-langflow-并开始一个新流程" aria-label="Permalink to &quot;打开 Langflow 并开始一个新流程&quot;">​</a></h2><p>点击 <strong>New Flow (新流程)</strong>，然后选择 <strong>Travel Planning Agent (旅行规划代理)</strong> 流程。</p><p>这将打开一个初始流程，包含运行使用多工具调用代理的智能应用所需的组件。</p><h2 id="创建旅行规划代理流程" tabindex="-1">创建旅行规划代理流程 <a class="header-anchor" href="#创建旅行规划代理流程" aria-label="Permalink to &quot;创建旅行规划代理流程&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><p><strong>旅行规划代理</strong>流程包括以下组件：</p><ul><li>多个<strong>工具调用代理</strong>组件，这些组件使用连接的LLM（大型语言模型）来推理用户的输入，并在连接的工具中进行选择以完成他们的任务。</li><li><strong>计算器</strong>组件执行基本的算术运算。</li><li><strong>URL内容获取器</strong>组件从给定的URL抓取内容。</li><li><strong>聊天输入</strong>组件接受用户输入到聊天中。</li><li><strong>聊天输出</strong>组件将流程的输出打印到聊天中。</li><li><strong>OpenAI</strong>模型组件将用户输入和提示发送到OpenAI API并接收响应。</li></ul><h2 id="运行旅行计划代理流程" tabindex="-1">运行旅行计划代理流程 <a class="header-anchor" href="#运行旅行计划代理流程" aria-label="Permalink to &quot;运行旅行计划代理流程&quot;">​</a></h2><ol><li>将您的凭证添加到 Open AI 和搜索 API 组件中。</li><li>点击 <strong>Playground</strong> 以启动一个聊天会话。您应该会收到一个详细且有帮助的回答，关于在 <strong>Chat input</strong> 组件中定义的行程。</li></ol><p>现在，您的查询已经从 <strong>Chat input</strong> 到 <strong>Chat output</strong> 完成了整个过程，您已经完成了 <strong>旅行计划代理</strong> 流程。</p>',18)]))}const u=n(e,[["render",l]]);export{f as __pageData,u as default};
